/* ------------------------------------------------------------------ */
/* 2. Os 1506 pagamentos de dez/2024 a nov/2025                        */
/* ------------------------------------------------------------------ */

-- `origem_ref` = vencimento + hash de (vencimento, categoria, descrição,
-- valor). O export não numera as linhas, e o número da linha mudaria a cada
-- re-exportação — o hash sobrevive a isso, que é o que faz o
-- `on conflict (fonte, origem_ref)` valer alguma coisa.
create temporary table _remuneracao_ca25 (
  pessoa      text not null,
  competencia date not null,
  bloco       text not null,
  valor       numeric(14,2) not null,
  origem_ref  text not null,
  categoria   text not null,
  vencimento  date not null,
  pagamento   date
) on commit drop;


-- Sem isto, quem não casasse sumiria calado: o insert abaixo é um join, e join
-- que não acha não grava e não reclama. Aqui ele reclama.
do $$
declare v_orfaos text;
begin
  select string_agg(distinct t.pessoa, ', ') into v_orfaos
    from _remuneracao_ca25 t
   where public.remuneracao_pessoa_por_chave(public.contraparte_chave(t.pessoa)) is null;
  if v_orfaos is not null then
    raise exception 'Remuneração/Conta Azul 2025: sem pessoa no cadastro para %', v_orfaos;
  end if;
end $$;

select public.remuneracao_pessoa_por_chave(public.contraparte_chave(t.pessoa)),
       t.competencia, t.bloco, t.valor, 'conta_azul', t.origem_ref,
       t.categoria, t.vencimento, t.pagamento
  from _remuneracao_ca25 t
on conflict (fonte, origem_ref) do update
  set valor         = excluded.valor,
      competencia   = excluded.competencia,
      bloco         = excluded.bloco,
      categoria     = excluded.categoria,
      vencimento    = excluded.vencimento,
      pagamento     = excluded.pagamento,
      pessoa_id     = excluded.pessoa_id,
      atualizado_em = now();

/* ------------------------------------------------------------------ */
/* 3. Conferência: a premiação tem de bater com a DRE de 2025          */
/* ------------------------------------------------------------------ */

-- O teste que provou a âncora fica gravado, para que uma reaplicação com dado
-- torto não passe em silêncio. Repare no deslocamento: a competência de um mês
-- é conferida contra a coluna do mês SEGUINTE da DRE, porque a DRE de 2025 é
-- caixa (ver o cabeçalho). Dez/2024 fica de fora — é a ponta da série, e a
-- coluna Dec-24 da DRE tem o que se pagou dentro de dezembro, que não veio.
do $$
declare
  r      record;
  v_prem numeric;
  v_dre  numeric;
begin
  for r in
    select * from (values
      ('2025-01-01'::date, 'Feb-25'), ('2025-02-01'::date, 'Mar-25'),
      ('2025-03-01'::date, 'Apr-25'), ('2025-04-01'::date, 'May-25'),
      ('2025-05-01'::date, 'Jun-25'), ('2025-06-01'::date, 'Jul-25'),
      ('2025-07-01'::date, 'Aug-25'), ('2025-08-01'::date, 'Sep-25'),
      ('2025-09-01'::date, 'Oct-25'), ('2025-10-01'::date, 'Nov-25')
    ) as c(competencia, chave_dre)
  loop
    select coalesce(sum(l.valor), 0) into v_prem
      from public.remuneracao_lancamento l
     where l.competencia = r.competencia and l.bloco = 'premiacao';

    -- O blob guarda o mês em INGLÊS e a despesa negativa; mês sem valor vem
    -- como string vazia, que o cast recusa.
    select coalesce(sum(abs(nullif(linha.value ->> r.chave_dre, '')::numeric)), 0) into v_dre
      from public.demonstracoes_contabeis d,
           lateral jsonb_array_elements(d.dados -> 'rows') linha
     where d.tipo = 'dre' and d.periodo = 'completo'
       and linha.value ->> 'Conta' in ('Premiações', 'Premiações Operacionais');

    if v_dre > 0 and abs(v_dre - v_prem) > 1 then
      raise exception 'Remuneração/% : premiação R$ % não bate com a DRE (R$ %)',
        r.chave_dre, v_prem, v_dre;
    end if;
  end loop;
end $$;
